pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }
    function testRegression_property() public {
        address from = address(0x123);
        address caddress = address(0x456);
        address[] memory tos = new address[](1);
        tos[0] = address(0x789);
        uint[] memory vals = new uint[](1);
        vals[0] = 100;

        bool ok;
        try c.transfer(from, caddress, tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "transfer should succeed with non-empty tos");
    }
}
